import java.util.Scanner;

public class Main {
    static long[] powers = new long[18];
    static int minimum_moves = 0;

    static void search(int current_sum, long remaining, int position) {
        if (current_sum > minimum_moves)
            return;
        if (remaining == 0) {
            minimum_moves = Math.min(minimum_moves, current_sum);
            return;
        }
        int needed = (int) (remaining / powers[position]);
        // First recursive call
        search(current_sum + (position * needed), remaining - (needed * powers[position]), position - 1);
        // Second recursive call
        needed++;
        search(current_sum + (needed * position), (needed * powers[position]) - remaining, position - 1);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long number = sc.nextLong();

        powers[1] = 1;
        for (int i = 2; i < 18; i++) {
            powers[i] = (10 * powers[i - 1]) + 1;
        }

        long temp = number;
        minimum_moves = 0;

        while (temp > 0) {
            for (int i = 1; i < 18; i++) {
                if (powers[i] > temp) {
                    minimum_moves += (i - 1);
                    temp -= powers[i - 1];
                    break;
                }
            }
        }

        search(0, number, 16);
        System.out.println(minimum_moves);
        sc.close();
    }
}
